async Task<List<Item>> BuildPlan(){var result=new List<Item>();foreach(var id in ids){
 var s=await test.PartProcessCharacteristics.AsNoTracking().Include(x=>x.Machine).Include(x=>x.Tank).Include(x=>x.Characteristic).SingleAsync(x=>x.Id==id);var p=await prod.PartProcessCharacteristics.AsNoTracking().Include(x=>x.Machine).Include(x=>x.Tank).Include(x=>x.Characteristic).SingleAsync(x=>x.Id==id);
 string Key(PartProcessCharacteristic x)=>$"{x.Machine?.MachineCode}|{x.Tank?.TankCode}|{x.Characteristic?.CharacteristicCode}|{x.Unit}";if(Key(s)!=Key(p)||!p.IsEnabled||p.IsDeleted||p.ControlScope!="CHEM"||p.Machine?.MachineCode!="QE2")throw new InvalidOperationException("Approved QE2 identity changed: "+id);
