 var sf=await test.ChemicalAnalysisFormulaVersions.AsNoTracking().SingleAsync(x=>x.Id==se.FormulaVersionId&&x.PartProcessCharacteristicId==id);var sh=await test.ChemicalFTableVersionHistories.AsNoTracking().SingleAsync(x=>x.Id==se.FTableHistoryId);var signature=SchedulePlan.FSignature(sh.CellsJson);
 var pp=await prod.ChemicalFormulaPolicies.AsNoTracking().SingleAsync(x=>x.PartProcessCharacteristicId==id);if(pp.ActiveScheduleRevisionId is not long active)throw new InvalidOperationException("No production active revision: "+id);var old=await prod.ChemicalFormulaEffectivities.AsNoTracking().Where(x=>x.PartProcessCharacteristicId==id&&x.ScheduleRevisionId==active).OrderBy(x=>x.EffectiveFromUtc).Select(x=>new Slice(x.EffectiveFromUtc,x.EffectiveUntilUtcExclusive,x.FormulaVersionId,x.FTableHistoryId)).ToListAsync();
 var sourceCalculation=CalculationSignature(sf.ConfigJson);var matchingFormulas=(await prod.ChemicalAnalysisFormulaVersions.AsNoTracking().Where(x=>x.PartProcessCharacteristicId==id).ToListAsync()).Where(x=>CalculationSignature(x.ConfigJson)==sourceCalculation).ToList();var activeFormulaIds=old.Select(x=>x.FormulaId).ToHashSet();var formula=matchingFormulas.Where(x=>activeFormulaIds.Contains(x.Id)).OrderByDescending(x=>x.VersionNo).FirstOrDefault()??(matchingFormulas.Count==1?matchingFormulas[0]:null)??throw new InvalidOperationException("No unambiguous matching production calculation formula: "+id);
 var matchingF=(await prod.ChemicalFTableVersionHistories.AsNoTracking().ToListAsync()).Where(x=>SchedulePlan.FSignature(x.CellsJson)==signature).ToList();var activeFIds=old.Where(x=>x.FId.HasValue).Select(x=>x.FId!.Value).ToHashSet();var f=matchingF.Where(x=>activeFIds.Contains(x.Id)).OrderByDescending(x=>x.VersionNo).FirstOrDefault()??matchingF.OrderBy(x=>x.Id).FirstOrDefault()??throw new InvalidOperationException("No matching production F snapshot: "+id);
 var merged=SchedulePlan.InsertClosedGap(old,from,until,formula.Id,f.Id);result.Add(new(id,Key(p),active,pp.IsEnabled,formula.Id,f.Id,se.FormulaVersionId,se.FTableHistoryId,merged));}
