var oldRevisions=await prod.ChemicalFormulaScheduleRevisions.AsNoTracking().OrderBy(x=>x.Id).ToListAsync();var oldEffects=await prod.ChemicalFormulaEffectivities.AsNoTracking().OrderBy(x=>x.Id).ToListAsync();var oldPolicies=await prod.ChemicalFormulaPolicies.AsNoTracking().OrderBy(x=>x.PartProcessCharacteristicId).ToListAsync();var maxRevision=oldRevisions.Max(x=>x.Id);var maxEffect=oldEffects.Max(x=>x.Id);
var sourceHash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(Serialize(plan.Select(x=>new{x.Id,x.Key,x.Formula,x.F,x.SourceFormula,x.SourceF})))));await File.WriteAllTextAsync(Path.Combine(args[2],stamp+"-before.json"),JsonSerializer.Serialize(new{task,mode,sourceHash,plan,before},options));Console.WriteLine($"{mode}: pending={changed}; sourceHash={sourceHash}");
